class Solution {
public:
    int minDeletionSize(vector<string>& strs) {
        int n = strs.size(), cols = strs[0].size();
        vector<bool> is_sorted(n - 1, false);
        int deleted = 0;
        for (int c = 0; c < cols; ++c) {
            bool bad = false;
            for (int i = 0; i < n - 1; ++i) {
                if (!is_sorted[i] && strs[i][c] > strs[i + 1][c]) {
                    bad = true;
                    break;
                }
            }
            if (bad) {
                deleted++;
            } else {
                for (int i = 0; i < n - 1; ++i) {
                    if (strs[i][c] < strs[i + 1][c]) is_sorted[i] = true;
                }
            }
        }
        return deleted;
    }
};

class Solution {
    public int minDeletionSize(String[] strs) {
        int n = strs.length, cols = strs[0].length();
        boolean[] isSorted = new boolean[n - 1];
        int deleted = 0;
        for (int c = 0; c < cols; c++) {
            boolean bad = false;
            for (int i = 0; i < n - 1; i++) {
                if (!isSorted[i] && strs[i].charAt(c) > strs[i + 1].charAt(c)) {
                    bad = true;
                    break;
                }
            }
            if (bad) {
                deleted++;
            } else {
                for (int i = 0; i < n - 1; i++) {
                    if (strs[i].charAt(c) < strs[i + 1].charAt(c)) {
                        isSorted[i] = true;
                    }
                }
            }
        }
        return deleted;
    }
}

var minDeletionSize = function(strs) {
    const n = strs.length, cols = strs[0].length;
    const isSorted = new Array(n - 1).fill(false);
    let deleted = 0;
    for (let c = 0; c < cols; c++) {
        let bad = false;
        for (let i = 0; i < n - 1; i++) {
            if (!isSorted[i] && strs[i][c] > strs[i + 1][c]) {
                bad = true;
                break;
            }
        }
        if (bad) {
            deleted++;
        } else {
            for (let i = 0; i < n - 1; i++) {
                if (strs[i][c] < strs[i + 1][c]) isSorted[i] = true;
            }
        }
    }
    return deleted;
};
